INSERT INTO calendars (title, category, description, icon, tier_required, status, start_date) VALUES ('Hiking Adventures', 'Hiking', 'Twenty-four outdoor mini-adventures: discover local trails, viewpoints, forests and hidden green spaces at your own pace.', 'ph-mountains', 'free', 'active', CURRENT_DATE - 11);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Pick Your Trail', 'Every great outing starts with a route that makes you curious.', 'Choose a nearby marked trail, waterfront path or greenway. Check distance, opening hours and the forecast, and save an easier alternative.', 1, 20, '10 mins', 'ph-map-trifold', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'The Scenic Detour', 'A small change of route can reveal a place you have never noticed.', 'Take a familiar, safe route and add one marked side path or viewpoint. Stay on public paths and turn back whenever you like.', 2, 20, '20 mins', 'ph-signpost', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Waterfront Wander', 'Following the water makes an ordinary walk feel like an expedition.', 'Find a public riverside, lake or seafront trail. Walk at an easy pace, check local access notices and enjoy the views.', 3, 20, '30 mins', 'ph-waves', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Forest Sound Safari', 'Listening closely turns the trail into a nature discovery game.', 'On a safe woodland path, pause three times and identify five different natural sounds. Keep a respectful distance from wildlife.', 4, 20, '25 mins', 'ph-tree-evergreen', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Summit or Viewpoint Mission', 'A destination gives your hike a satisfying sense of adventure.', 'Choose a marked route to a viewpoint that fits your ability and daylight. Bring water, check the weather and skip exposed routes in poor conditions.', 5, 20, '45 mins', 'ph-mountains', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Photo Scavenger Hike', 'A playful photo mission helps you notice details along the way.', 'On an easy public trail, photograph a leaf shape, an interesting texture, a wide view and a trail marker. Do not leave the path for a shot.', 6, 30, '30 mins', 'ph-camera', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Wildflower Spotting', 'Seasonal colour makes the same trail feel different every time.', 'Look for three different wildflowers from the path. Use a local guide or app if you like; do not pick plants or enter protected areas.', 7, 20, '25 mins', 'ph-flower', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Sunrise Trail Adventure', 'Early light can make a familiar landscape feel brand new.', 'Only if the route is open and conditions are safe, visit a nearby easy trail around sunrise. Tell someone your plan, bring a light and turn back if visibility is poor.', 8, 20, '35 mins', 'ph-sun-horizon', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Park-to-Park Explorer', 'Connecting green spaces makes a city feel full of hidden trails.', 'Plan a walk between two public parks using sidewalks and marked paths. Choose a route with a simple shortcut back to your starting point.', 9, 20, '35 mins', 'ph-park', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Creekside Discovery', 'A small stream offers plenty of details to discover at a gentle pace.', 'Follow a marked path beside a creek or canal. Stay on the trail, keep away from slippery banks and notice how the landscape changes.', 10, 20, '30 mins', 'ph-drop', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Trail Map Challenge', 'Using a map adds a little expedition feeling to your outing.', 'Pick a short, well-marked loop and follow a downloaded map. Check your location at trail junctions; do not rely on mobile signal alone.', 11, 20, '30 mins', 'ph-compass', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Leave No Trace Hike', 'Caring for a trail helps keep it beautiful for the next explorer.', 'Bring a small bag and pick up litter only when it is safe to do so. Leave plants, rocks and wildlife where they are, and follow local disposal rules.', 12, 30, '30 mins', 'ph-leaf', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Golden Hour Loop', 'Warm evening light makes a simple loop feel like a special outing.', 'Choose an easy loop with enough daylight to finish comfortably. Check sunset time, bring a charged phone and head back early if the weather changes.', 13, 20, '30 mins', 'ph-sun', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Hill Repeats, Your Pace', 'A gentle climb can turn a local hill into a mini adventure.', 'Choose a short, safe slope on a public path. Walk up once, rest, and repeat only if comfortable. Skip steep or slippery ground and take the easy route down.', 14, 20, '25 mins', 'ph-trend-up', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Find a Hidden Garden', 'Small gardens and green corners can be surprising trail destinations.', 'Find a public garden, arboretum or community green space. Check opening times and explore its marked paths at your own pace.', 15, 20, '30 mins', 'ph-tree', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Cloudscape Viewpoint', 'Looking up gives even a short walk a fresh perspective.', 'Walk to a safe open viewpoint or park bench. Notice three cloud shapes and how the light shifts; avoid exposed high ground during storms.', 16, 20, '25 mins', 'ph-cloud-sun', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Choose-your-own Loop', 'A route you design yourself feels like your own little expedition.', 'Connect two or three marked paths into a loop suited to your time and ability. Save the map offline and share your route with someone.', 17, 20, '40 mins', 'ph-path', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Bridge-to-Bridge Trek', 'Landmarks turn a trail into a point-to-point discovery.', 'Find a safe public path between two bridges or trail landmarks. Use crossings and walkways only; do not enter roadways or restricted areas.', 18, 30, '35 mins', 'ph-bridge', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Nature Journal Walk', 'A few notes make small discoveries memorable without turning them into a task.', 'Bring a pocket notebook on an easy trail. Sketch or jot down one surprising thing you noticed, then put the notebook away and enjoy the rest.', 19, 20, '25 mins', 'ph-notebook', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Choose a New Trailhead', 'Starting somewhere new is an easy way to make a local adventure feel fresh.', 'Use a local parks or trails directory to pick a public trailhead you have not visited. Check transport, parking, access and route difficulty first.', 20, 20, '40 mins', 'ph-map-pin', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Wildlife-Watching Walk', 'Quiet observation can reveal birds and other wildlife along the trail.', 'Bring binoculars if you have them and stay quietly on a marked path. Observe from a distance, never feed or approach animals.', 21, 20, '30 mins', 'ph-binoculars', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Rain-or-Shine Nature Quest', 'A light change in weather can make familiar scenery feel completely different.', 'If local advisories allow, take a short, sheltered public path with weather-appropriate layers. Avoid storms, flooding, icy routes and exposed terrain; an indoor nature-map quest is a fine alternative.', 22, 20, '20 mins', 'ph-umbrella', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Pack a Trail Picnic', 'A snack stop turns a hike into a mini day out.', 'Choose a short route with a permitted rest spot. Pack water and a snack, check local food and fire rules, and carry every wrapper back out.', 23, 20, '40 mins', 'ph-basket', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Hiking Adventures'), 'Your Grand Finale: Favourite View', 'Finish the calendar by revisiting the moment or place you most enjoyed.', 'Choose a safe marked route to your favourite viewpoint from this calendar, or pick a new easy trail. Take a photo, celebrate the adventure and plan another outing only if it sounds fun.', 24, 30, '45 mins', 'ph-flag-checkered', 'free', FALSE);
INSERT INTO calendars (title, category, description, icon, tier_required, status, start_date) VALUES ('Fitness Challenge', 'Fitness', 'Exercises and movement challenges for every level. Advanced sessions are Premium.', 'ph-barbell', 'free', 'active', CURRENT_DATE - 11);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Morning Mobility', 'Gentle movement wakes the body up.', 'Do 10 neck circles, 10 arm circles, 10 hip circles and 10 slow squats. Breathe deeply throughout.', 1, 20, '5 mins', 'ph-person-simple-tai-chi', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), '10-Minute Walk', 'Walking lifts mood and energy.', 'Walk briskly outdoors for 10 minutes. Leave your phone in your pocket and notice your surroundings.', 2, 20, '10 mins', 'ph-footprints', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Push-up Ladder', 'Builds upper-body strength anywhere.', 'Do 1 push-up, rest, 2 push-ups, rest, up to 6. Use your knees if needed and keep your back straight.', 3, 20, '8 mins', 'ph-barbell', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Squat Challenge', 'Strong legs support every movement.', 'Do 3 sets of 15 bodyweight squats with 45 seconds rest. Keep your chest up and knees over toes.', 4, 20, '8 mins', 'ph-arrow-fat-line-down', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Plank Hold', 'Core strength protects your back.', 'Hold a forearm plank for as long as you can with good form. Rest 1 minute and try again. Beat your time.', 5, 20, '5 mins', 'ph-timer', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Stairs Sprint', 'Short bursts boost cardio quickly.', 'Climb a flight of stairs at a fast pace 6 times, walking down to recover.', 6, 20, '10 mins', 'ph-stairs', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Interval Cardio Blast', 'Intervals raise fitness efficiently.', 'Alternate 40 seconds of jumping jacks, high knees and burpees with 20 seconds rest. 5 rounds.', 7, 40, '15 mins', 'ph-heartbeat', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Full-Body Strength Circuit', 'Balanced strength work builds resilience.', 'Do 4 rounds: 12 squats, 10 push-ups, 12 lunges per leg, 30 s plank. Rest 60 s between rounds.', 8, 40, '20 mins', 'ph-barbell', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Flexibility Flow', 'Stretching reduces stiffness and injury risk.', 'Hold each stretch for 30 seconds: hamstrings, quads, hip flexors, shoulders, chest, back. Do two rounds.', 9, 20, '12 mins', 'ph-flower-lotus', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Balance Practice', 'Balance keeps you stable as you move.', 'Stand on one leg for 45 seconds, eyes open, then 20 seconds eyes closed. Switch legs. Do 3 rounds.', 10, 20, '6 mins', 'ph-scales', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'HIIT Finisher', 'High intensity burns fat and builds stamina.', 'Do 8 rounds of 30 seconds all-out mountain climbers followed by 30 seconds of rest. Cool down with slow walking.', 11, 40, '15 mins', 'ph-fire', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Jump Rope Basics', 'Skipping builds rhythm and cardio.', 'Skip for 30 seconds, rest 30 seconds, for 8 rounds. No rope? Mime the swing and jump on the spot.', 12, 20, '8 mins', 'ph-lightning', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Lunge Walk', 'Lunges train legs and balance together.', 'Take 12 long lunging steps forward, then 12 back. Keep your front knee over your ankle. Do 3 rounds.', 13, 20, '8 mins', 'ph-footprints', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Core Circuit', 'A strong core steadies everything you do.', 'Do 30 seconds each of dead bugs, bicycle crunches and side planks per side. Rest 30 seconds. Repeat 3 times.', 14, 20, '10 mins', 'ph-timer', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Tempo Run Intervals', 'Mixing paces trains speed and stamina.', 'Jog 3 minutes easy, run 2 minutes at a hard but steady pace. Repeat 4 times and walk to cool down.', 15, 40, '20 mins', 'ph-heartbeat', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Wall Sit Challenge', 'Isometric holds build leg endurance.', 'Hold a wall sit with thighs parallel to the floor for 40 seconds. Rest 30 seconds. Repeat 5 times.', 16, 20, '6 mins', 'ph-arrow-fat-line-down', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Shoulder & Back Strength', 'Posture improves when the upper back is strong.', 'Do 3 sets of 12 superman holds, 12 reverse snow angels and 10 pike push-ups with 40 seconds rest.', 17, 20, '12 mins', 'ph-barbell', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Pyramid Strength Session', 'Pyramids add volume without losing form.', 'Do squats and push-ups in a pyramid: 4, 6, 8, 10, 8, 6, 4 reps of each. Rest 20 seconds between sets.', 18, 40, '25 mins', 'ph-barbell', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Nature Walk & Notice', 'Time outdoors lifts mood and eases stress.', 'Walk somewhere green for 15 minutes. Find five different colours and listen for three separate sounds.', 19, 20, '15 mins', 'ph-footprints', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Dance Break', 'Movement you enjoy keeps you coming back.', 'Pick three songs you love and dance freely to all of them. No rules, just keep moving.', 20, 20, '10 mins', 'ph-music-notes', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Hill or Stair Repeats', 'Climbing builds power quickly.', 'Find a hill or stairs. Climb for 45 seconds at a strong effort and walk down. Repeat 8 times.', 21, 40, '15 mins', 'ph-stairs', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Hip & Glute Stretch Flow', 'Open hips reduce lower-back strain.', 'Hold pigeon pose, figure-four and low lunge for 45 seconds per side. Breathe slowly the whole time.', 22, 20, '10 mins', 'ph-flower-lotus', 'free', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Weekly Movement Plan', 'A simple plan makes consistency easy.', 'Pick three days and a 20-minute activity for each. Write them down and tell someone about your plan.', 23, 20, '10 mins', 'ph-notebook', 'free', TRUE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Fitness Challenge'), 'Active Recovery & Review', 'Recovery is part of training.', 'Do a gentle walk and stretch, then write down what felt strongest this calendar and your next fitness goal.', 24, 20, '10 mins', 'ph-leaf', 'free', FALSE);
INSERT INTO calendars (title, category, description, icon, tier_required, status, start_date) VALUES ('Football Skills Calendar', 'Football', 'Drills, tactics and match-day practice to sharpen your football. Premium calendar.', 'ph-soccer-ball', 'premium', 'active', CURRENT_DATE - 11);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Ball Mastery Warm-up', 'Close control is the base of every football skill.', 'Using a ball, do 2 minutes each of sole rolls, inside-outside taps, and toe taps. Keep the ball within one step of your feet.', 1, 30, '10 mins', 'ph-soccer-ball', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Juggling Challenge', 'Juggling sharpens touch and coordination.', 'Try to keep the ball in the air with feet, thighs and shoulders. Beat your own record and note the number of touches.', 2, 30, '10 mins', 'ph-soccer-ball', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Passing Wall', 'Accurate passing wins matches.', 'Stand 5 metres from a wall. Play 30 passes with your right foot, 30 with your left, controlling each return in one touch.', 3, 30, '15 mins', 'ph-arrows-left-right', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Dribbling Slalom', 'Dribbling in tight spaces builds confidence under pressure.', 'Set up 6 markers (shoes, bottles) one metre apart. Dribble through and back 5 times, then repeat using only your weaker foot.', 4, 30, '15 mins', 'ph-path', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Shooting Accuracy', 'Placement beats power.', 'Take 15 shots at the corners of a goal or a marked target. Aim low into each corner and score your hits out of 15.', 5, 30, '15 mins', 'ph-target', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Watch & Learn: Tactics', 'Reading the game improves your decisions.', 'Watch 20 minutes of a match and track one player off the ball. Write down 3 positioning choices you would copy.', 6, 30, '20 mins', 'ph-television', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'First Touch Drill', 'A good first touch creates time and space.', 'Throw the ball up and cushion it with thigh, chest or foot so it stops dead within a metre. Repeat 20 times.', 7, 30, '10 mins', 'ph-hand-pointing', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Footwork Ladder', 'Quick feet improve agility and balance.', 'Draw a ladder with chalk or tape. Run through it with one foot in each box, then two feet in each box, then lateral steps. 6 rounds.', 8, 30, '10 mins', 'ph-footprints', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Small-Sided Game', 'Match situations make skills stick.', 'Organise a 3v3 or 5v5 kick-about with friends. Rotate teams and practise calling for the ball loudly.', 9, 30, '30 mins', 'ph-users-three', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Set-Piece Practice', 'Set pieces decide close games.', 'Practise 10 free kicks and 10 corners from a fixed spot. Aim at a target area and track how many reach it.', 10, 30, '20 mins', 'ph-flag', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Football Fitness Circuit', 'Match fitness is repeated sprinting.', 'Do 10 x 20 m sprints with 30 seconds rest, then 3 sets of 10 squat jumps. Finish with a gentle jog.', 11, 30, '20 mins', 'ph-lightning', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Reflect & Set a Goal', 'Goals keep your practice purposeful.', 'Write down your best moment from this calendar and one skill you will focus on next month.', 12, 30, '10 mins', 'ph-notebook', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Weak Foot Passing', 'A reliable weaker foot makes you unpredictable.', 'Play 40 passes against a wall using only your weaker foot, then 20 first-time passes. Count your clean receptions.', 13, 30, '15 mins', 'ph-arrows-left-right', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'First Touch Control', 'A good first touch buys you time.', 'Throw the ball up or bounce it off a wall and control it with thigh, chest and foot. Aim for 10 controlled touches in a row.', 14, 30, '12 mins', 'ph-soccer-ball', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Turns and Feints', 'Changing direction beats defenders.', 'Practise the drag-back, Cruyff turn and step-over 10 times each, first slowly and then at match pace.', 15, 30, '15 mins', 'ph-path', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Crossing Practice', 'Good delivery creates chances.', 'Hit 15 crosses into a marked area from the wing, with both feet if you can. Note how many land in the target zone.', 16, 30, '20 mins', 'ph-target', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Heading Technique', 'Safe heading technique wins aerial duels.', 'Use a light ball. Practise standing headers against a wall, using your forehead and keeping your eyes open.', 17, 30, '10 mins', 'ph-soccer-ball', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Goalkeeping Basics', 'Understanding the keeper helps every player.', 'Practise diving saves to each side, catching with W-shaped hands and getting up quickly. Do 10 per side.', 18, 30, '15 mins', 'ph-hand-grabbing', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Speed and Agility Cones', 'Quick changes of direction win loose balls.', 'Set 4 cones in a square 5 metres apart. Sprint, shuffle, backpedal and shuffle round it. Do 8 rounds.', 19, 30, '15 mins', 'ph-lightning', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Understanding Formations', 'Shape and roles decide how teams play.', 'Draw a 4-4-2 and a 4-3-3. Write one job for each position and one strength of each shape.', 20, 30, '20 mins', 'ph-television', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'One-Touch Passing Patterns', 'Fast passing moves defenders out of position.', 'With a partner or wall, play passing triangles using one touch only. Keep going for 3 minutes without losing the ball.', 21, 30, '20 mins', 'ph-arrows-left-right', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Pressing and Tackling Drill', 'Winning the ball back quickly changes games.', 'Practise closing down a partner at an angle, staying low and timing a clean tackle. Swap roles after 10 attempts.', 22, 30, '15 mins', 'ph-users-three', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Penalty Routine', 'A calm routine beats pressure.', 'Take 10 penalties using the same routine each time: pick a corner, breathe out, strike. Record how many you score.', 23, 30, '15 mins', 'ph-flag', 'premium', FALSE);
INSERT INTO activities (calendar_id, title, description, instructions, day_number, points, duration, icon, tier_required, randomizer_eligible) VALUES ((SELECT id FROM calendars WHERE title = 'Football Skills Calendar'), 'Full Match Review', 'Reviewing play turns experience into learning.', 'Replay a match you took part in or watched. Note three things that worked and three things to improve next week.', 24, 30, '20 mins', 'ph-notebook', 'premium', FALSE);
